package com.keqi.reminder;

import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import org.json.*;

/** Regression scenarios from the independent implementation review. */
public final class ReviewRegressionTests {
    private static int checks;
    private static void check(boolean ok,String label){checks++;if(!ok)throw new AssertionError(label);}
    private static void remove(Path folder) throws Exception {try(java.util.stream.Stream<Path> files=Files.walk(folder)){for(Path file:(Iterable<Path>)files.sorted(Comparator.reverseOrder())::iterator)Files.deleteIfExists(file);}}
    private static void platformRace(boolean reconnect) throws Exception {
        Path folder=Files.createTempDirectory("keqi-read-race-");ExecutorService reader=Executors.newSingleThreadExecutor();
        try(DesktopStore store=new DesktopStore(folder)){
            JSONObject original=new JSONObject().put("connected",true).put("platform","chaoxing").put("sourceAccount","7").put("generation","old");store.meta("connection.chaoxing",original);
            CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);
            Http.transport=request->{if(request.optString("stage").equals("cookies")){entered.countDown();if(!release.await(5,TimeUnit.SECONDS))throw new AssertionError("read not released");return new JSONObject().put("cookies","_uid=7");}return new JSONObject().put("status",200).put("url",request.getString("url")).put("html","<script>var uid=7;</script><li><a href='/mycourse/studentcourse?courseId=101&clazzid=202&cpi=303' title='概率论'>进入课程</a></li>");};
            Future<?> reading=reader.submit(()->{try{new Platforms(store).read("chaoxing");throw new AssertionError("stale read committed");}catch(InterruptedException expected){}catch(Exception e){throw new RuntimeException(e);}});
            check(entered.await(5,TimeUnit.SECONDS),"read reaches the delayed session response");
            JSONObject current=reconnect?new JSONObject(original.toString()).put("generation","new").put("message","new connection"):new JSONObject().put("platform","chaoxing").put("status","unconfigured");store.meta("connection.chaoxing",current);release.countDown();reading.get(5,TimeUnit.SECONDS);
            check(store.meta("connection.chaoxing").similar(current),reconnect?"old read cannot replace a newer connection":"old read cannot undo disconnect");
            check(store.transact(w->w.list("course").length())==0,"stale read cannot commit source observations");
        }finally{reader.shutdownNow();remove(folder);}
    }
    private static void cancelledPairing() throws Exception {
        Path folder=Files.createTempDirectory("keqi-pair-race-");ExecutorService approval=Executors.newSingleThreadExecutor();
        try(DesktopStore store=new DesktopStore(folder)){
            store.meta("lan.intent",new JSONObject().put("id","pending-pair"));store.meta("lan.connection",new JSONObject().put("fingerprint","original"));store.meta("lan.credentials",new JSONObject().put("token","old-sealed-token"));CountDownLatch waiting=new CountDownLatch(1),release=new CountDownLatch(1);
            Future<Boolean> delayed=approval.submit(()->{waiting.countDown();release.await(5,TimeUnit.SECONDS);try{store.transact(w->{LinkSession.requireIntent(store.meta("lan.intent"),"pending-pair");store.meta("lan.credentials",new JSONObject().put("token","late-sealed-token"));store.meta("lan.connection",new JSONObject().put("fingerprint","late"));return null;});return false;}catch(IllegalArgumentException cancelled){return true;}});
            check(waiting.await(5,TimeUnit.SECONDS),"pairing is waiting for computer approval");store.transact(w->{store.meta("lan.intent",new JSONObject().put("id","unlinked"));store.meta("lan.connection",new JSONObject());store.meta("lan.credentials",new JSONObject());return null;});release.countDown();check(delayed.get(5,TimeUnit.SECONDS),"late approval is cancelled by unlink");check(store.meta("lan.connection").length()==0&&store.meta("lan.credentials").length()==0,"cancelled pairing cannot restore association or credentials");
            try{store.transact(w->{store.meta("lan.credentials",new JSONObject().put("token","must-roll-back"));store.meta("lan.connection",new JSONObject().put("fingerprint","must-roll-back"));throw new java.io.IOException("simulated pairing write failure");});}catch(java.io.IOException expected){}check(store.meta("lan.connection").length()==0&&store.meta("lan.credentials").length()==0,"pairing credentials and association roll back together");
        }finally{approval.shutdownNow();remove(folder);}
    }
    public static void main(String[] args) throws Exception {
        Workspace w=new Workspace(new JSONObject());JSONObject course=new JSONObject().put("key","chaoxing:101:202").put("platform","chaoxing").put("title","概率论");JSONObject task=new JSONObject().put("id","legacy").put("platform","chaoxing").put("courseKey",course.getString("key")).put("sourceId","901").put("phase","submit").put("title","第一章").put("kind","homework").put("status","pending").put("due",1800000000000L).put("lastSeen",1);
        w.observe("chaoxing","7",new JSONArray().put(course),new JSONArray().put(task),false,true);JSONObject backup=new JSONObject().put("format","keqi-data-v1").put("snapshot",new JSONObject(w.snapshot(-1).toString()));
        task.put("status","done").put("due",1800003600000L).put("lastSeen",2);w.observe("chaoxing","7",new JSONArray().put(course),new JSONArray().put(task),false,true);w.importArchive(backup,true);JSONObject latest=w.get("legacy");
        check(latest.getString("status").equals("done")&&latest.getLong("due")==1800003600000L,"old backup cannot roll back a verified platform status or deadline");check(!latest.optBoolean("sourceConflict"),"historical backup does not create a live source disagreement");
        Workspace recurring=new Workspace(new JSONObject());TaskService service=new TaskService(recurring,true);long from=java.time.Instant.parse("2030-01-01T00:00:00Z").toEpochMilli();String series=service.command("createTask",new JSONObject().put("title","晨读").put("repeat",new JSONObject().put("frequency","daily").put("start","2030-01-01T09:00").put("timezone","Asia/Shanghai"))).getString("id");Repeats.materialize(recurring,from,from+3*86400000L,true);JSONObject instance=null;JSONArray instances=recurring.list("manual");for(int i=0;i<instances.length();i++)if(instances.getJSONObject(i).getString("slot").equals("2030-01-02"))instance=instances.getJSONObject(i);check(instance!=null,"future slot generated");String instanceId=instance.getString("id");service.command("addSubtask",new JSONObject().put("parent",instanceId).put("title","读第二章"));service.command("changeSeries",new JSONObject().put("id",series).put("rule",new JSONObject().put("frequency","weekly").put("start","2030-01-01T10:00").put("timezone","Asia/Shanghai")));JSONArray visible=service.tasks(false);JSONObject retained=null;for(int i=0;i<visible.length();i++)if(visible.getJSONObject(i).getString("id").equals(instanceId))retained=visible.getJSONObject(i);check(retained!=null&&retained.optBoolean("seriesReplaced")&&retained.getJSONArray("subtasks").length()==1,"subtask-only edited slot stays visible after recurrence rule changes");
        Workspace phone=new Workspace(new JSONObject());phone.join(recurring.id());phone.receive(recurring.snapshot(-1));String step=retained.getJSONArray("subtasks").getJSONObject(0).getString("id");service.command("updateSubtask",new JSONObject().put("id",step).put("title","电脑版本").put("done",true));new TaskService(phone,false).command("updateSubtask",new JSONObject().put("id",step).put("title","手机版本").put("done",false));JSONArray operations=phone.pending();for(int i=0;i<operations.length();i++)recurring.apply(operations.getJSONObject(i),true);JSONObject conflicting=recurring.get(step);check(conflicting.getJSONArray("conflicts").length()==2&&!conflicting.getBoolean("done"),"step conflicts preserve candidates and conservatively retain pending work");service.command("resolveConflict",new JSONObject().put("id",step).put("values",new JSONObject().put("title","合并步骤").put("done",true)).put("bases",conflicting.getJSONObject("fieldVersions")));check(recurring.get(step).getJSONArray("conflicts").length()==0,"step conflicts can be explicitly resolved");
        JSONObject legacy=new JSONObject().put("id","legacy-notice").put("platform","chaoxing").put("status","pending").put("version",4).put("due",1000).put("manualDue",1500).put("deadlineChanged",true).put("deadlineEventVersion",3),local=LocalNotices.fromLegacy(legacy),project=new JSONObject(legacy.toString()).put("id","shared-id");LocalNotices.annotate(project,local);check(project.getString("noticeId").equals("legacy-notice")&&project.getInt("version")==4&&project.getInt("deadlineEventVersion")==3,"migration preserves old notification identity and deadline event");project.put("note","备注修改");LocalNotices.annotate(project,local);check(project.getInt("version")==4,"note editing does not create another deadline notice");project.put("due",2000);LocalNotices.annotate(project,local);int event=project.getInt("deadlineEventVersion");check(project.getBoolean("deadlineChanged")&&event>3&&project.getInt("version")==4,"real source deadline change remains detectable with a manual date override");LocalNotices.annotate(project,local);check(project.getInt("deadlineEventVersion")==event,"unchanged projection does not emit another deadline event");project.put("manualDue",2500);LocalNotices.annotate(project,local);check(project.getInt("version")==5,"effective reminder date edit increments only the local reminder version");
        JSONObject link=new JSONObject().put("workspace","workspace").put("fingerprint","certificate").put("link","first");check(LinkSession.matches(link,new JSONObject(link.toString())),"active phone pairing accepts its response");check(!LinkSession.matches(new JSONObject(),link),"unlink rejects a late sync response");check(!LinkSession.matches(new JSONObject(link.toString()).put("link","second"),link),"re-pair rejects the old request generation");
        platformRace(false);platformRace(true);cancelledPairing();System.out.println("Review regression checks passed: "+checks);
    }
}
